# ============================================================================
# s30: Main benchmark — tuned methods × suite problems × dims × seeds
# ============================================================================
#
# Runs every method at its fine-tuned per-problem config (read from the
# s20-generated configs/autogenerated_finetuned_parameters_presets.jl) on the
# full suite, recording results under script='s30'. The head-to-head for the paper.
#
#   - Tuned params : include(configs/autogenerated_finetuned_parameters_presets.jl)
#                    → TUNED_PARAMS, TUNED_CONVERGED.
#                    Each method is built as T(:Pk; TUNED_PARAMS[(name(T),Pk)]...).
#   - Tolerance    : eps = native_tol(P) (D1, source-paper criterion).
#   - Budget       : maxiter = universal_maxiter(P, eps) (tolerance-aware, uniform).
#   - Stopping     : NativeResStopping(native, eps) + MaxIterStopping + NanStopping.
#   - Dims/seeds   : P1{64,128,256} P2{100,300,600,900} P3{50,100,200}
#                    P4{256,512} P5{128,512,1024};
#                    20 seeds for P3, 10 otherwise (3 each under --quick).
#   - Production   : a full run (no --quick) writes production=1 rows (the paper
#                    data); --quick writes production=0. The two tiers coexist in
#                    the DB (production is in the PK) and never clobber each other;
#                    paper tables/figures filter production=1.
#   - CPU timing   : `reps` solves per cell (default 3; iters/flag/residual are
#                    deterministic — taken from rep 1; cpu_time = median over reps).
#   - History      : collected for ONE representative cell per (method,problem)
#                    (reference dim, seed1) so s70 can draw convergence panels.
#   - DNC          : EPCM on P4 is expected DNC at native tol (TUNED_CONVERGED) —
#                    recorded honestly as flag=:maxiter, not a crash.
#
# Usage:
#   julia --project=jcode jcode/scripts/s30_benchmark.jl
#   julia --project=jcode jcode/scripts/s30_benchmark.jl --quick
#   julia --project=jcode jcode/scripts/s30_benchmark.jl --methods=EPCM,IFRAB --problems=P2,P3 --reps=5 --force
#   julia --project=jcode jcode/scripts/s30_benchmark.jl --methods=EPCM --problems=P4 --eps=1e-4 --maxiter=6000 --force
#   julia --project=jcode jcode/scripts/s30_benchmark.jl --summary       # report only (no run): per-problem ranking from the DB
# Output: console + results/logs/log_s30_benchmark_<ts>.txt ; rows tagged script='s30'.
# Skips already-done cells unless --force. --summary reads the production tier (production=1, or 0 with --quick).
# --eps / --maxiter override the native tolerance / tolerance-aware budget (applied to every --problems
# cell in the run); both enter make_config_hash, so override runs are DISTINCT rows from default-tol runs.

include(joinpath(@__DIR__, "..", "src", "includes.jl"))
using Statistics

# ── tuned params (generated by s20's promotion step) ────────────────────────
const TUNED_JL = joinpath(JCODE_ROOT, "configs", "autogenerated_finetuned_parameters_presets.jl")
isfile(TUNED_JL) ||
    error("s30: $(TUNED_JL) not found. Run the s20 sweep (all method×problem cells) first.")
include(TUNED_JL)   # defines const TUNED_PARAMS, TUNED_CONVERGED

const S30_METHODS    = (AEFBFP, MAEFBFP, MTTM, IMTTM, RFBSM, IRFBSM)  # reporting order (proposals first)
const S30_PROBLEMS   = ("P1", "P2", "P3", "P4")
const S30_DIMS       = Dict("P1" => [64, 128, 256], "P2" => [100, 300, 600, 900],
                            "P3" => [50, 100, 200], "P4" => [256, 512])
const S30_REFDIM     = Dict("P1" => 128, "P2" => 300, "P3" => 100, "P4" => 256,
                            )  # history cell
const METHOD_BY_NAME = Dict(name(T) => T for T in (S30_METHODS..., MFRBSM))

# ── tiny ARG parser ──────────────────────────────────────────────────────────
function parse_cli(args)
    opts = Dict{String,String}(); flags = String[]
    for a in args
        startswith(a, "--") || continue
        kv = split(a[3:end], "="; limit = 2)
        length(kv) == 2 ? (opts[kv[1]] = kv[2]) : push!(flags, kv[1])
    end
    return opts, flags
end

# Build a method at its tuned per-problem config.
function build_alg(::Type{T}, P::AbstractString) where {T}
    key = (name(T), P)
    haskey(TUNED_PARAMS, key) ||
        error("s30: no tuned params for $key in $(basename(TUNED_JL)) — run s20 for this cell first.")
    return T(Symbol(P); TUNED_PARAMS[key]...)
end

# Run one (method, problem, dim, seed) cell with `reps` timing repetitions.
# Returns a NamedTuple summary, or `nothing` if skipped.
function run_cell(db, T, prob, P, dim, init, eps, maxiter, reps, run_id;
                  collect_hist::Bool, force::Bool, production::Bool)
    alg        = build_alg(T, P)
    hash, hin  = make_config_hash(alg, P, eps, maxiter)
    ensure_config!(db, alg, P, eps, maxiter, hash, hin)
    if !force && is_done(db, hash, P, dim, init.label; script = "s30", production = production)
        return nothing
    end

    cpus         = Float64[]
    hist_records = IterRecord[]
    local result, nat
    for rep in 1:reps
        # Fresh stoppers each rep (ResidualStopping/NativeResStopping carry de-bounce state).
        stopping = (NativeResStopping(prob.native_residual, eps),
                    MaxIterStopping(maxiter), NanStopping())
        nrec = NativeResRecorder(prob.native_residual)
        if rep == 1 && collect_hist
            hc     = HistoryCallback()
            result = solve(alg, prob, copy(init.x0); stopping = stopping, observers = (hc, nrec))
            hist_records = hc.history
        else
            result = solve(alg, prob, copy(init.x0); stopping = stopping, observers = (nrec,))
        end
        push!(cpus, result.cpu_time)
        nat = nrec.value
    end

    med_cpu = median(cpus)
    # SolverResult is immutable; reconstruct with the median CPU (other fields deterministic).
    result_med = make_result(converged = result.converged, iterations = result.iterations,
                             f_evals = result.f_evals, cpu_time = med_cpu, x = result.x,
                             flag = result.flag, residual = result.residual,
                             scaled_residual = result.scaled_residual)
    insert_result!(db, hash, P, dim, init.label, init.seed_idx, run_id, result_med;
                   script = "s30", native_residual = nat, production = production)
    if collect_hist && !isempty(hist_records)
        insert_history!(db, hash, P, dim, init.label, init.seed_idx, hist_records;
                        script = "s30", production = production)
    end
    return (converged = result.converged, iters = result.iterations,
            cpu = med_cpu, flag = result.flag, nat = nat)
end

# Final summary: aggregate ALL s30 rows in the DB (robust to skips) per (method, problem).
function print_s30_summary(db, tee, production::Bool)
    df = DBInterface.execute(db, """
        SELECT c.method AS method, r.problem AS problem, r.converged AS conv,
               r.iterations AS iters, r.cpu_time AS cpu, c.eps AS eps, c.maxiter AS maxiter, r.config_hash AS config_hash
        FROM results r JOIN configs c ON r.config_hash = c.config_hash
        WHERE r.script='s30' AND r.production=?
    """, (production ? 1 : 0,)) |> DataFrame
    df = filter(r -> is_canonical(r.problem, r.eps, r.maxiter), df)   # canonical config only
    cur = current_canonical_configs(db; production = production)
    df  = filter(r -> r.config_hash in cur, df)                       # pin to the live tuned config
    println(tee, "\n--- s30 summary (median over seeds & dims; production=$(production ? 1 : 0); canonical config) ---")
    @printf(tee, "  %-6s %-4s %8s %10s %12s\n", "method", "prob", "conv", "med_iter", "med_cpu(s)")
    println(tee, "  " * "-" ^ 46)
    med(v) = isempty(v) ? NaN : median(v)
    for T in S30_METHODS, P in S30_PROBLEMS
        sub = df[(df.method .== name(T)) .& (df.problem .== P), :]
        nrow(sub) == 0 && continue
        conv = sub[sub.conv .== 1, :]
        mi   = isempty(conv) ? "—" : string(Int(round(med(float.(conv.iters)))))
        mc   = isempty(conv) ? med(float.(sub.cpu)) : med(float.(conv.cpu))
        @printf(tee, "  %-6s %-4s %4d/%-3d %10s %12.4f\n",
                name(T), P, nrow(conv), nrow(sub), mi, mc)
    end
end

# (method, problem) cells excluded from the --summary ranking (known artifacts).
# MTTM/P1 and MTTM/P5: α₁=1 forces the first computed iterate to 0. On zero-solution
# problems (P1, P5) that produces trivial "convergence" in ~2 iters, so these cells
# are not real algorithmic wins and are dropped from the ranking.
const SUMMARY_EXCLUDE = Set([("MTTM", "P1"), ("MTTM", "P5")])
# A method that solved < ROBUST_FRAC of its (seed × dim) instances on a problem is "weak":
# it is ranked AFTER the robust solvers, so a lucky-fast minority can never top the list.
const ROBUST_FRAC = 0.5

# Per-problem ranking for ONE metric column (lower = better): robust solvers first (by value
# asc), then weak partial solvers, then DNC. `show_frac` appends the solved count k/n —
# convergence is metric-independent, so we show it on the Iterations block only.
function _rank_block(df, tee, title::AbstractString, col::Symbol, fmt; show_frac::Bool=false)
    println(tee, "\n$title:")
    for P in S30_PROBLEMS
        ranks = NamedTuple[]
        for T in S30_METHODS
            (name(T), P) in SUMMARY_EXCLUDE && continue
            sub  = df[(df.method .== name(T)) .& (df.problem .== P), :]
            nrow(sub) == 0 && continue
            conv  = sub[sub.conv .== 1, :]
            nconv = nrow(conv); ntot = nrow(sub)
            v     = nconv > 0 ? median(float.(conv[!, col])) : Inf
            frac  = ntot > 0 ? nconv / ntot : 0.0
            push!(ranks, (m = name(T), v = v, nconv = nconv, ntot = ntot, frac = frac))
        end
        isempty(ranks) && continue
        sort!(ranks, by = r -> (r.frac < ROBUST_FRAC, r.v, r.m))   # robust first; value asc; DNC last
        parts = String[]
        for r in ranks
            if !isfinite(r.v)
                push!(parts, "$(r.m)(DNC)")
            elseif show_frac
                push!(parts, "$(r.m)($(fmt(r.v)), $(r.nconv)/$(r.ntot))")
            else
                push!(parts, "$(r.m)($(fmt(r.v)))")
            end
        end
        @printf(tee, "  %-3s: %s\n", P, join(parts, " > "))
    end
end

# --summary display: per-problem rankings for iterations, CPU time, and operator evals.
function print_comparison(db, tee, production::Bool)
    df = DBInterface.execute(db, """
        SELECT c.method AS method, r.problem AS problem, r.converged AS conv,
               r.iterations AS iters, r.cpu_time AS cpu, r.f_evals AS fe,
               c.eps AS eps, c.maxiter AS maxiter, r.config_hash AS config_hash
        FROM results r JOIN configs c ON r.config_hash = c.config_hash
        WHERE r.script='s30' AND r.production=?
    """, (production ? 1 : 0,)) |> DataFrame
    df = filter(r -> is_canonical(r.problem, r.eps, r.maxiter), df)   # canonical config only
    cur = current_canonical_configs(db; production = production)
    df  = filter(r -> r.config_hash in cur, df)                       # pin to the live tuned config
    println(tee, "\n" * "=" ^ 70)
    println(tee, "  s30 comparison — production=$(production ? 1 : 0)  (best > worst, lower = better;")
    println(tee, "  median over converged seeds & dims; k/n = solved instances (shown on Iterations);")
    println(tee, "  weak solvers (<50% solved) ranked after robust ones; canonical config; DNC = none solved)")
    isempty(SUMMARY_EXCLUDE) ||
        println(tee, "  excluded artifact(s): ", join(["$m/$p" for (m, p) in SUMMARY_EXCLUDE], ", "))
    println(tee, "=" ^ 70)
    if nrow(df) == 0
        println(tee, "  (no s30 production=$(production ? 1 : 0) rows yet — run s30 first.)")
        return
    end
    _rank_block(df, tee, "Iterations", :iters, v -> string(Int(round(v))); show_frac=true)
    _rank_block(df, tee, "CPU (s)",    :cpu,   v -> @sprintf("%.4g", v))
    _rank_block(df, tee, "Evals",      :fe,    v -> string(Int(round(v))))
end

function main()
    opts, flags = parse_cli(ARGS)
    quick = "quick" in flags
    production = !quick   # full runs are production (paper) data; --quick runs are not
    force = "force" in flags
    reps  = haskey(opts, "reps") ? parse(Int, opts["reps"]) : (quick ? 1 : 3)
    methods = haskey(opts, "methods") ?
        Tuple(METHOD_BY_NAME[String(strip(m))] for m in split(opts["methods"], ",")) : S30_METHODS
    problems = haskey(opts, "problems") ?
        String[String(strip(p)) for p in split(opts["problems"], ",")] : collect(S30_PROBLEMS)

    logpath, tee, _ = setup_logging("s30_benchmark")
    db     = open_db()
    run_id = "s30_$(Dates.format(now(), "yyyymmdd_HHMMSS"))"

    if "summary" in flags                          # report-only: rank from the DB, no benchmark run
        print_s30_summary(db, tee, production)
        print_comparison(db, tee, production)
        teardown_logging(tee, logpath)
        return nothing
    end

    mlist  = join(name.(methods), ",")
    plist  = join(problems, ",")

    println(tee, "=" ^ 80)
    println(tee, "  s30 benchmark — tuned-vs-tuned, $(length(S30_METHODS)) methods × suite   $(Dates.now())")
    println(tee, "  reps=$reps  quick=$quick  production=$(production ? 1 : 0)  force=$force  run_id=$run_id")
    println(tee, "  methods=$mlist  problems=$plist")
    println(tee, "=" ^ 80)

    n_run = 0; n_skip = 0; n_err = 0
    for P in problems
        prob_id = parse(Int, P[2:end])
        # --eps / --maxiter override the per-problem native tolerance and the
        # tolerance-aware budget. Both enter make_config_hash, so override runs
        # land in DISTINCT config rows (they never collide with default runs).
        eps     = haskey(opts, "eps")     ? parse(Float64, opts["eps"]) : native_tol(P)
        maxiter = haskey(opts, "maxiter") ? parse(Int, opts["maxiter"]) : universal_maxiter(P, eps)
        n_seeds = quick ? 3 : (P == "P3" ? 20 : 10)
        dims    = quick ? [S30_REFDIM[P]] : S30_DIMS[P]
        ovr     = (haskey(opts, "eps") || haskey(opts, "maxiter")) ? "  (override)" : ""
        @printf(tee, "\n  [%s] eps=%.1e  maxiter=%d  seeds=%d  dims=%s%s\n",
                P, eps, maxiter, n_seeds, string(dims), ovr)
        for dim in dims
            prob = get_problem(prob_id; dim = dim, n_seeds = n_seeds)   # P3 now takes dim = K too
            rdim = prob.dim
            inits = get_initial_points(prob)
            for T in methods
                expected_dnc = haskey(TUNED_CONVERGED, (name(T), P)) && !TUNED_CONVERGED[(name(T), P)]
                cell = NamedTuple[]
                for init in inits
                    collect_hist = (rdim == S30_REFDIM[P]) && (init.seed_idx == 1)
                    try
                        r = run_cell(db, T, prob, P, rdim, init, eps, maxiter, reps, run_id;
                                     collect_hist = collect_hist, force = force, production = production)
                        if r === nothing
                            n_skip += 1
                        else
                            n_run += 1
                            push!(cell, r)
                        end
                    catch e
                        n_err += 1
                        @printf(tee, "  %-6s %-3s dim=%-4d %-8s *** EXCEPTION ***\n",
                                name(T), P, rdim, init.label)
                        showerror(tee, e, catch_backtrace()); println(tee)
                    end
                end
                if !isempty(cell)
                    nconv = count(c -> c.converged, cell)
                    mi    = nconv > 0 ? string(Int(round(median([float(c.iters) for c in cell if c.converged])))) : "—"
                    mc    = median([c.cpu for c in cell])
                    @printf(tee, "  %-6s %-3s dim=%-4d  %3d/%-3d conv  med_iter=%-8s med_cpu=%.4f%s\n",
                            name(T), P, rdim, nconv, length(cell), mi, mc,
                            expected_dnc ? "   [expected DNC @ native tol]" : "")
                end
            end
        end
    end

    @printf(tee, "\n  Cells: %d run, %d skipped (already done), %d errored.\n", n_run, n_skip, n_err)
    print_s30_summary(db, tee, production)
    print_comparison(db, tee, production)
    println(tee, "\n  Done. Rows tagged script='s30'. Next: s70 figures/tables.")
    teardown_logging(tee, logpath)
    return nothing
end

main()
